import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC01%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E5%8C%96%E5%8F%91%E5%B1%95/1.1%20%E4%BF%A1%E6%81%AF%E5%8C%96%E6%A6%82%E5%BF%B5.html","title":"1.1 信息与信息化","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第01章 信息化发展/1.1 信息化概念.md"}`),a={name:`1.1 信息化概念.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_1-1-信息与信息化" tabindex="-1"><a class="header-anchor" href="#_1-1-信息与信息化"><span>1.1 信息与信息化</span></a></h1><h2 id="_1-1-1-信息" tabindex="-1"><a class="header-anchor" href="#_1-1-1-信息"><span>1.1.1 信息</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><ol><li>信息是物质、能量及其属性的标示的集合，是确定性的增加。</li><li>它以物质介质为载体，传递和反映世界各种事物存在方式、运动状态等的表征。<strong>信息不是物质，也不是能力。</strong></li><li>香农:信息是用来消除随机不确定性的东西</li><li>在热力学中,熵是系统无序程度的度量,信息是系统有序程度的度量,表现为负熵</li></ol><h3 id="特征" tabindex="-1"><a class="header-anchor" href="#特征"><span>特征</span></a></h3><p>信息的特征包括客观性、普遍性、无限性、动态性、相对性、依附性、变换性、传递性、层次性、系统性和转化性等</p><h3 id="质量属性" tabindex="-1"><a class="header-anchor" href="#质量属性"><span>质量属性</span></a></h3><ol><li>信息质量属性主要包括精确性、完整性、可靠性、及时性、经济性、可验证性和安全性等</li><li>对于金融信息而言,其最重要的特性是<strong>安全性</strong></li><li>对于经济与社会信息而言,其最重要的特性是<strong>及时性</strong></li></ol><h2 id="_1-1-2-信息系统" tabindex="-1"><a class="header-anchor" href="#_1-1-2-信息系统"><span>1.1.2 信息系统</span></a></h2><h3 id="组合" tabindex="-1"><a class="header-anchor" href="#组合"><span>组合</span></a></h3><ol><li><strong>管理模型</strong>：指系统服务对象领域的专门知识，以及分析和处理该领域问题的模型，又称为对象的处理模型</li><li><strong>信息处理模型</strong>：指系统处理信息的结构和方法。管理模型中的理论和分析方法在信息处理模型中转化为信息获取、存储、传输、加工和使用的规则</li><li><strong>系统实现条件</strong>：指可供应用的计算机技术和通信技术、从事对象领域工作的人员以及对这些资源的控制与融合</li></ol><h3 id="组成部件" tabindex="-1"><a class="header-anchor" href="#组成部件"><span>组成部件</span></a></h3><p>信息系统的组成部件包括硬件、软件、数据库、网络、存储设备、感知设备、外设、人员以及把数据处理成信息的规程等</p><h3 id="特点" tabindex="-1"><a class="header-anchor" href="#特点"><span>特点</span></a></h3><ol><li>信息系统产生、建设、运行和完善构成一个循环的过程，遵循一定规律</li><li>信息系统建设周期长、投资大、风险大，比一般技术工程有更大的难度和复杂性，其在使用过程中，随着生存环境的变化，需要不断维护和修改，当它不再适应的时候就要被淘汰，由新系统代替老系统</li></ol><h3 id="信息系统生命周期" tabindex="-1"><a class="header-anchor" href="#信息系统生命周期"><span>信息系统生命周期</span></a></h3><h4 id="软件的生命周期" tabindex="-1"><a class="header-anchor" href="#软件的生命周期"><span>软件的生命周期</span></a></h4><p>可行性分析与项目开发计划、需求分析、概要设计、详细设计、编码、测试、维护等阶段</p><h4 id="信息系统的生命周期-记忆-划分即实行" tabindex="-1"><a class="header-anchor" href="#信息系统的生命周期-记忆-划分即实行"><span>信息系统的生命周期（记忆：划分即实行）</span></a></h4><ol><li><strong>系统规划</strong>：可行性分析与项目开发计划</li><li><strong>系统分析</strong>：需求分析</li><li><strong>系统设计</strong>：概要设计、详细设计</li><li><strong>系统实施</strong>：<strong>编码、测试</strong></li><li><strong>系统运行和维护</strong></li></ol><h2 id="_1-1-3-信息化" tabindex="-1"><a class="header-anchor" href="#_1-1-3-信息化"><span>1.1.3 信息化</span></a></h2><h3 id="_1-信息化的核心" tabindex="-1"><a class="header-anchor" href="#_1-信息化的核心"><span>① 信息化的核心</span></a></h3><p>通过全体社会成员的共同努力，在经济和社会各个领域充分应用基于信息技术的先进社会生产工具，提高信息时代的社会生产力，并推动生产关系和上层建筑的改革，使国家的综合实力、社会的文明程度和人民的生活质量全面提升</p><h3 id="_2-信息化内涵-记忆-网产运码" tabindex="-1"><a class="header-anchor" href="#_2-信息化内涵-记忆-网产运码"><span>② 信息化内涵（记忆：网产运码）</span></a></h3><ol><li><strong>信息网络体系</strong>：信息资源、各种信息系统、公用通信网络平台</li><li><strong>信息产业基础</strong>：信息科学技术研究与开发、信息装备制造、信息咨询服务</li><li><strong>社会运行环境</strong>：现代工农业、管理体制、政策法律、规章制度、文化教育、道德观念等生产关系与上层建筑</li><li><strong>效用积累过程</strong>：劳动者素质、国家现代化水平和人民生活质量的不断提高，精神文明和物质文明建设不断进步</li></ol><h3 id="_3-信息化体系6要素" tabindex="-1"><a class="header-anchor" href="#_3-信息化体系6要素"><span>③ 信息化体系6要素</span></a></h3><ol><li>信息技术应用</li><li>信息资源</li><li>信息网络</li><li>信息技术和产业</li><li>信息化人才</li><li>信息化政策法规和标准规范</li></ol><h3 id="_4-信息化趋势" tabindex="-1"><a class="header-anchor" href="#_4-信息化趋势"><span>④ 信息化趋势</span></a></h3><p>【主要：驱动和加速组织转型升级和生产力建设】</p><ol><li><strong>产品信息化</strong><ol><li>产品中各类信息比重日益增大、物质比重日益降低其物质产品的特征向信息产品的特征迈进</li><li>越来越多的产品中嵌入了智能化元器件，使产品具有越来越强的信息处理功能</li></ol></li><li><strong>产业信息化</strong>：农业、工业、服务业等传统产业广泛利用信息技术</li><li><strong>社会生活信息化</strong>：市场、科技、教育、军事、政务、日常生活等在内的整个社会体系采用先进的信息技术</li><li><strong>国民经济信息化</strong>：在经济大系统内实现统一的信息大流动，使金融、贸易、投资、计划、营销等组成一个信息大系统</li></ol><h4 id="国家信息化趋势-记忆-2020" tabindex="-1"><a class="header-anchor" href="#国家信息化趋势-记忆-2020"><span>国家信息化趋势（记忆：2020…）</span></a></h4><ol><li><strong>第一步到2020年</strong></li></ol><p>核心关键技术部分领域达到国际先进水平，信息产业国际竞争力大幅提升，信息化成为驱动现代化建设的先导力量</p><ol start="2"><li><strong>第二步到2025年</strong></li></ol><p>建成国际领先的移动通信网络，根本改变核心关键技术受制于人的局面，实现技术先进、产业发达、<strong>应用领先、网络安全</strong>坚不可摧的战略目标，涌现一批具有强大国际竞争力的大型跨国网信企业</p><ol start="3"><li><strong>第三步到21世纪中叶</strong></li></ol><p>信息化全面支撑富强民主文明和谐的社会主义现代化国家建设，网络强国地位日益巩固，在引领全球信息化发展方面有更大作为</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};